import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root object for this node
  const root = new Group();
  root.position.set(0, -0.3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Create plane geometry based on atlas aspect (512x320)
  const aspect = 512 / 320; // 1.6
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Basic material – will receive texture later
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.opacity = 1.0;
  material.color = new Color('#ffffff');

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  let texture = null;
  texturePromise.then((tex) => {
    texture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  // No primitives to apply for this node
  const primitiveInstances = [];

  // No text content for this node
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    });
    root.add(textObj);
  }

  // Handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    for (const p of primitiveInstances) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // Dispose texture
    if (texture) {
      texture.dispose();
      texture = null;
    }
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();
    // Kill any GSAP timelines (none in this node, but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
